#include <bits/stdc++.h>
using namespace std;

#define rep(i, n) for(int i = 0; i < n; ++i)

int main(void) {
	int n,q,t,x,y,ans;
	cin>>n>>q;
	vector<set<int>>e(n);
	set<int>::iterator itr;
	ans=n;
	rep(i,q){
		cin>>t;
		if(t==1){
			cin>>x>>y;
			x--,y--;
			if(e[x].size()==0)ans--;
			if(e[y].size()==0)ans--;
			e[x].insert(y);
			e[y].insert(x);
		}
		else{
			cin>>x;
			x--;
			itr=e[x].begin();
			while(itr!=e[x].end()){
				y=*itr;
				e[y].erase(x);
				if(e[y].size()==0)ans++;
				itr++;
			}
			if(e[x].size()>0)ans++;
			e[x].clear();
		}
		cout<<ans<<endl;
	}
	return 0;
}

